import io

from google.cloud import storage


def create_presigned_download_url(object_name, config=None):
    config = config or {}
    client = storage.Client(project=config["project_id"])
    blob = client.bucket(config["bucket"]).blob(object_name)
    url = blob.generate_signed_url(expiration=3600)
    return {"url": url}

from google.cloud import storage


def get_object_metadata(object_name, config=None):
    config = config or {}
    client = storage.Client(project=config["project_id"])
    blob = client.bucket(config["bucket"]).blob(object_name)
    metadata = blob.metadata
    return {"metadata": metadata}

from google.cloud import storage


def list_objects_with_prefix(prefix, config=None):
    config = config or {}
    client = storage.Client(project=config["project_id"])
    blobs = client.list_blobs(config["bucket"], prefix=prefix)
    objects = [blob.name for blob in blobs]
    return {"objects": objects}

from google.cloud import storage


def get_storage_client(config):
    return storage.Client(project=config["project_id"])


def get_bucket(client, bucket_name):
    return client.bucket(bucket_name)

class Payload:
    def __init__(self, object_name, data, content_type="application/octet-stream"):
        self.object_name = object_name
        self.data = data
        self.content_type = content_type


class Response:
    def __init__(self, status, message):
        self.status = status
        self.message = message

from google.cloud import vision


def ocr_stored_document(object_name, config=None):
    config = config or {}
    client = vision.ImageAnnotatorClient()
    image = vision.Image()
    image.source.image_uri = f"gs://{config['bucket']}/{object_name}"
    response = client.document_text_detection(image=image)
    text = response.full_text_annotation.text
    return {"text": text}

from google.cloud import translate_v2 as translate


def translate_stored_text(text, target_language, config=None):
    config = config or {}
    client = translate.Client()
    translation = client.translate(text, target_language=target_language)
    return {"translated_text": translation['translatedText']}

from google.cloud import language_v1 as language


def summarize_stored_asset(object_name, config=None):
    config = config or {}
    client = language.LanguageServiceClient()
    document = language.Document()
    document.content = object_name
    document.type_ = language.Document.Type.PLAIN_TEXT
    summary = client.analyze_sentiment(document=document).document_sentiment.text
    return {"summary": summary}

from google.cloud import language_v1 as language


def embed_asset_metadata(metadata, config=None):
    config = config or {}
    client = language.LanguageServiceClient()
    document = language.Document()
    document.content = metadata
    document.type_ = language.Document.Type.PLAIN_TEXT
    embedding = client.analyze_sentiment(document=document).document_sentiment.score
    return {"embedding": embedding}
